from pathlib import Path
import json,hashlib,re
p=Path(__file__).resolve().parent;read=lambda n:json.loads((p/n).read_text());pct=lambda a,b:round((b/a-1)*100,3)
runtime=read('runtime-manifest.json');snapshot=read('bench-runtime-sha256.json')
for row in runtime:assert hashlib.sha256((p/'runtime'/row['path']).read_bytes()).hexdigest()==row['sha256']==snapshot['candidate'][row['path']]
assert re.search(r'^# pass 1892$',(p/'tests.log').read_text(),re.M) and re.search(r'^# fail 0$',(p/'tests.log').read_text(),re.M)
first=[]
for name in ['native-first-load-results.json','native-filled-first-load-results.json']:
 d=read(name);rows=[]
 for r in d['comparisons']:
  a,b=r['baseline'],r['candidate'];rows.append({'scenario':r['scenario'],'baseline':a,'candidate':b,'elapsedPercent':pct(a['medianMs'],b['medianMs']),'peakHeapPercent':pct(a['sampledMaxHeapBytes'],b['sampledMaxHeapBytes'])})
 first.append({'report':name,'processes':len(d['runs']),'rows':rows})
jsc=read('vocal-jsc-results.json');mixed=read('mixed-native-churn-results.json');pressure=read('native-pressure-results.json');features=read('feature-results.json');live=read('live-vocal-language-results.json')
summary={'version':'3.1.7','adapter':15,'baselineVersion':'3.1.6','baselineRuntime':'4f5d87583a44364de3495a4f9902a5abb4756ae6','tests':{'passed':1892,'failed':0,'addedSince316':151,'egernYAML':'passed'},'runtime':runtime,'firstLoad':first,'jsc':jsc,'mixedChurn':{'configurations':len(mixed['results']),'responses':sum(r['lyricResponses'] for r in mixed['results']),'warmHTTP':sum(r['warmHTTP'] for r in mixed['results']),'peakHTTP':max(r['maxActiveHTTP'] for r in mixed['results'])},'pressure':{'processes':len(pressure['runs']),'peakLiveInvocations':max(r['peakLiveInvocations'] for r in pressure['runs']),'peakHTTP':max(r['peakHTTP'] for r in pressure['runs']),'admissionTimers':max(r['admissionTimers'] for r in pressure['runs'])},'featureInvocations':features['invocations'],'liveProbe':live,'limitsChanged':False,'scope':'Functional repair plus compiled native mocks and desktop Node/macOS JSC measurements. Not iPhone UI, every transient allocation, native network buffers or VPN acceptance. Cold time uses zero service latency; all regressions are retained.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# VerseLyrics 3.1.7 validation and measurements','',summary['scope'],'', '## Functional scope','', '- 1892 automated tests pass, 151 new since 3.1.6; native Egern YAML validation passes.','- Ninety new native client/format test cases cover English/Chinese vocal suppression, joined/hidden formatting, French/Japanese/Korean short-word translation, warm caches, label changes, meaningful English/Chinese fragments and fallback source translations, including preserved language after static replacement.','- Chinese conversion-only guards remain. Eight previous Japanese/Korean-labelled mixed-row expectations now preserve foreign short-word eligibility under the requested language boundary; their Chinese text still stays literal.','- Old cache/source/official translations cannot bypass the filter. No global cache purge, extra cache, new native API or higher capacity/concurrency is required.','', '## First-load comparison','', 'Six alternating fresh-process trials per case/version, 32 MiB Node old-space. One newly compiled native script/context per process. Both versions use the same codec and fixture responses. Empty and populated-cache tables each include seventeen cases and 204 processes; populated cases start with 48000-60000 unrelated cache characters. Output hashes and HTTP counts must agree in these unchanged ordinary cases. Sampled process heap includes the harness/compiler/code cache and is not every transient peak.','']
for group in first:
 lines+=['### '+group['report'],'', '| Scenario | Baseline ms | Candidate ms | Time change | Sampled heap change |','| --- | ---: | ---: | ---: | ---: |']
 for r in group['rows']:lines.append(f"| {r['scenario']} | {r['baseline']['medianMs']:.3f} | {r['candidate']['medianMs']:.3f} | {r['elapsedPercent']:+.3f}% | {r['peakHeapPercent']:+.3f}% |")
 lines.append('')
lines+=['## macOS JavaScriptCore','', jsc['scope'],'', '| Case | Version | Processing ms | Peak footprint bytes | Max RSS bytes | HTTP |','| --- | --- | ---: | ---: | ---: | ---: |']
for r in jsc['comparisons']:
 for version in ['baseline','candidate']:
  if version in r:
   v=r[version];lines.append(f"| {r['scenario']} | {version} | {v['milliseconds']:.3f} | {v['sampledPeakFootprint']:.0f} | {v['maxRSS']:.0f} | {v['result']['calls']} |")
lines+=['', '## Limits and repeated arrivals','', '- Twenty native client/format/cache-mode mixed playlists produce 4800 lyric responses. Warm cache reopen makes zero service requests; sampled active HTTP remains one.','- Sixteen arrival-pressure processes retain at most two live invocations, one active HTTP and zero admission timers in the fixture. Native storage admission remains advisory, not atomic; mock counts are not a phone concurrency guarantee.','- Sixty general native feature invocations retain static replacement on/off, source fallback, vocal filtering, mixed English, colors and cache limits.','- The candidate-only 600-row JSC vocal fixtures produce zero HTTP for English fillers and one batched request for three unique French short words, while removing official alternatives.','- Formerly skipped foreign words can now require translation by design, within the existing 64 original rows per batch, 6800 URL characters, 96 KiB reply and 2.5-second window. No extra retry or concurrency is added.','', '## Live short-word probe','', live['scope'],'', '| Source | Self-written input | Current result |','| --- | --- | --- |']
for r in live['results']:
 for a,b in zip(r['words'],r['translations']):lines.append(f"| {r['source']} | {a} | {b} |")
lines+=['','These responses confirm current request shape and outputs for these words only. They do not validate a full song, all future language detection, catalog coverage or phone rendering. The public endpoint is separate from paid Google Cloud Translation and has no claimed official contract.','', '## Interpretation and reproduction','', 'This release repairs classification. No universal speed or memory gain is asserted; all first-load and JSC regressions remain above. Runtime bytes and hashes are in runtime-manifest.json, and every comparison step checks that neither side changes. Full raw trials accompany the tables. First-load processing excludes real network wait. Existing cache, body, serial request and timeout limits are unchanged.','', 'Use README.md reproduction commands with unchanged 3.1.6 runtimes. Live probes use only self-written words. iPhone host response buffers, Spotify UI and VPN stability remain unmeasured.']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'tests':1892,'firstLoadProcesses':sum(r['processes'] for r in first),'jscProcesses':len(jsc['runs']),'mixedResponses':summary['mixedChurn']['responses'],'liveRequests':len(live['results'])}))
